SELECT 'p3 rdxset_t' AS SRC, COUNT(*) AS N_ROWS, SUM(CASE WHEN COLL IS NULL OR TRIM(CAST(COLL AS STRING)) = '' OR LOWER(TRIM(CAST(COLL AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_COLL, SUM(CASE WHEN CUST_RDXCUST IS NULL OR TRIM(CAST(CUST_RDXCUST AS STRING)) = '' OR LOWER(TRIM(CAST(CUST_RDXCUST AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_CUST_RDXCUST
FROM `${hivevar:tmp_db}`.`${hivevar:prefix}RDXSET_T`
UNION ALL
SELECT 'p4 rdxset_r' AS SRC, COUNT(*) AS N_ROWS, SUM(CASE WHEN COLL IS NULL OR TRIM(CAST(COLL AS STRING)) = '' OR LOWER(TRIM(CAST(COLL AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_COLL, SUM(CASE WHEN CUST_RDXCUST IS NULL OR TRIM(CAST(CUST_RDXCUST AS STRING)) = '' OR LOWER(TRIM(CAST(CUST_RDXCUST AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_CUST_RDXCUST
FROM `${hivevar:tmp_db}`.`${hivevar:prefix}RDXSET_R`;
